import { LinearGradient } from 'expo-linear-gradient'
import { MotiView } from 'moti'
import { CodePreviewBlock } from './blocks/CodePreviewBlock'
import { colors, useTheme } from '@/theme'
import { defineStyles } from '@/utils'
import { useEffect, useState } from 'react'
import Animated, {
	useSharedValue,
	useAnimatedStyle,
	withTiming,
	Easing
} from 'react-native-reanimated'

const GRADIENT_LENGTH = 64
const CONTAINER_HEIGHT = 200
const PIXEL_TRANSLATION = 100
const PIXEL_TRANSLATION_DURATION = 5000 // 5 seconds

export const CodePreviewContainer = ({ code }: { code: string }) => {
	const { theme } = useTheme()

	const translateY = useSharedValue(0)
	const [contentHeight, setContentHeight] = useState(0)

	const hasOverflow = contentHeight >= CONTAINER_HEIGHT

	useEffect(() => {
		if (!hasOverflow) {
			translateY.value = 0
			return
		}

		const scrollDistance = contentHeight - CONTAINER_HEIGHT
		const duration =
			(scrollDistance / PIXEL_TRANSLATION) * PIXEL_TRANSLATION_DURATION // {PIXEL_TRANSLATION} pixels per {PIXEL_TRANSLATION_DURATION} milliseconds

		translateY.value = withTiming(-scrollDistance, {
			duration: duration,
			easing: Easing.linear
		})
	}, [hasOverflow, contentHeight, translateY])

	const scrollStyle = useAnimatedStyle(() => {
		return {
			transform: [{ translateY: translateY.value }]
		}
	})

	return (
		<MotiView
			from={{ opacity: 0, height: 0 }}
			animate={{ opacity: 1, height: CONTAINER_HEIGHT }}
			exit={{ opacity: 0, height: 50 }}
			transition={{ type: 'timing', duration: 300 }}
			style={{ overflow: 'hidden' }}
		>
			<LinearGradient
				colors={[`${colors[theme].gray[25]}FF`, `${colors[theme].gray[25]}00`]}
				style={[
					styles.gradient,
					styles.gradientOverlayTop,
					{ display: hasOverflow ? 'flex' : 'none' }
				]}
			/>
			<LinearGradient
				colors={[`${colors[theme].gray[25]}00`, `${colors[theme].gray[25]}FF`]}
				style={[styles.gradient, styles.gradientOverlayBottom]}
			/>
			<LinearGradient
				colors={[`${colors[theme].gray[25]}00`, `${colors[theme].gray[25]}FF`]}
				start={{ x: 1, y: 0.5 }}
				end={{ x: 0, y: 0.5 }}
				style={[styles.gradient, styles.gradientOverlayLeft]}
			/>
			<LinearGradient
				colors={[`${colors[theme].gray[25]}00`, `${colors[theme].gray[25]}FF`]}
				start={{ x: 0, y: 0.5 }}
				end={{ x: 1, y: 0.5 }}
				style={[styles.gradient, styles.gradientOverlayRight]}
			/>
			<Animated.View
				style={[styles.codePreviewContainer, scrollStyle]}
				onLayout={(e) => {
					const height = e.nativeEvent.layout.height
					if (height > 0) setContentHeight(height)
				}}
			>
				<CodePreviewBlock code={code} />
			</Animated.View>
		</MotiView>
	)
}

const styles = defineStyles({
	gradient: {
		position: 'absolute',
		zIndex: 1
	},
	gradientOverlayTop: {
		top: 0,
		left: 28,
		width: '100%',
		height: GRADIENT_LENGTH
	},
	gradientOverlayBottom: {
		bottom: 0,
		left: 28,
		width: '100%',
		height: GRADIENT_LENGTH
	},
	gradientOverlayLeft: {
		left: 28,
		top: 0,
		width: GRADIENT_LENGTH / 2,
		height: '100%'
	},
	gradientOverlayRight: {
		right: 0,
		top: 0,
		width: GRADIENT_LENGTH / 2,
		height: '100%'
	},
	codePreviewContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		width: 1000
	}
})
